"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[54927],{14150:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>a,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>o,toc:()=>d});var n=h(31085),s=h(71184);const i={sidebar_position:20,slug:"/bible/Luke/Luke_20",title:"Luke 20",hide_table_of_contents:!0},r="Luke",o={id:"bible/Luke/Luke 20",title:"Luke 20",description:"Chapter 20",source:"@site/docs/bible/Luke/Luke 20.md",sourceDirName:"bible/Luke",slug:"/bible/Luke/Luke_20",permalink:"/docs/bible/Luke/Luke_20",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Luke/Luke 20.md",tags:[],version:"current",sidebarPosition:20,frontMatter:{sidebar_position:20,slug:"/bible/Luke/Luke_20",title:"Luke 20",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Luke 19",permalink:"/docs/bible/Luke/Luke_19"},next:{title:"Luke 21",permalink:"/docs/bible/Luke/Luke_21"}},a={},d=[{value:"Chapter 20",id:"chapter-20",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"luke",children:"Luke"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-20",children:"Chapter 20"}),"\n",(0,n.jsx)(t.p,{children:"The parable of the husbandmen.  Of paying tribute to Caesar and of the resurrection of the dead."}),"\n",(0,n.jsx)(h,{verse:1,children:"And it came to pass that on one of the days, as he was teaching the people in the temple and preaching the gospel, the chief priests and the scribes, with the ancients, met together,"}),"\n",(0,n.jsx)(h,{verse:2,children:"And spoke to him, saying: Tell us, by what authority dost thou these things? Or, who is he that hath given thee this authority?"}),"\n",(0,n.jsx)(h,{verse:3,children:"And Jesus answering, said to them: I will also ask you one thing. Answer me:"}),"\n",(0,n.jsx)(h,{verse:4,children:"The baptism of John, was it from heaven, or of men?"}),"\n",(0,n.jsx)(h,{verse:5,children:"But they thought within themselves, saying: If we shall say, From heaven: he will say: Why then did you not believe in him?"}),"\n",(0,n.jsx)(h,{verse:6,children:"But if we say, of men: the whole people will stone us. For they are persuaded that John was a prophet."}),"\n",(0,n.jsx)(h,{verse:7,children:"And they answered that they knew not whence it was."}),"\n",(0,n.jsx)(h,{verse:8,children:"And Jesus said to them: Neither do I tell you by what authority I do these things."}),"\n",(0,n.jsx)(h,{verse:9,children:"And he began to speak to the people this parable: A certain man planted a vineyard and let it out to husbandmen: and he was abroad for a long time."}),"\n",(0,n.jsx)(h,{verse:10,children:"And at the season he sent a servant to the husbandmen, that they should give him of the fruit of the vineyard. Who, beating him, sent him away empty."}),"\n",(0,n.jsx)(h,{verse:11,children:"And again he sent another servant. But they beat him also and, treating him reproachfully, sent him away empty."}),"\n",(0,n.jsx)(h,{verse:12,children:"And again he sent the third: and they wounded him also and cast him out."}),"\n",(0,n.jsx)(h,{verse:13,children:"Then the lord of the vineyard said: What shall I do? I will send my beloved son. It may be, when they see him, they will reverence him."}),"\n",(0,n.jsx)(h,{verse:14,children:"Whom, when the husbandmen saw, they thought within themselves, saying: This is the heir. Let us kill him, that the inheritance may be ours."}),"\n",(0,n.jsx)(h,{verse:15,children:"So casting him out of the vineyard, they killed him. What therefore will the lord of the vineyard do to them?"}),"\n",(0,n.jsx)(h,{verse:16,children:"He will come and will destroy these husbandmen and will give the vineyard to others. Which they hearing, said to him: God forbid."}),"\n",(0,n.jsx)(h,{verse:17,children:"But he looking on them, said: What is this then that is written, The stone, which the builders rejected, the same is become the head of the corner?"}),"\n",(0,n.jsx)(h,{verse:18,children:"Whosoever shall fall upon that stone shall be bruised: and upon whomsoever it shall fall, it will grind him to powder."}),"\n",(0,n.jsx)(h,{verse:19,children:"And the chief priests and the scribes sought to lay hands on him the same hour: but they feared the people, for they knew that he spoke this parable to them."}),"\n",(0,n.jsx)(h,{verse:20,children:"And being upon the watch, they sent spies, who should feign themselves just, that they might take hold of him in his words, that they might deliver him up to the authority and power of the governor."}),"\n",(0,n.jsx)(h,{verse:21,children:"And they asked him, saying: Master, we know that thou speakest and teachest rightly: and thou dost not respect any person, but teachest the way of God in truth."}),"\n",(0,n.jsx)(h,{verse:22,children:"Is it lawful for us to give tribute to Caesar, or no?"}),"\n",(0,n.jsx)(h,{verse:23,children:"But he, considering their guile, said to them: Why tempt you me?"}),"\n",(0,n.jsx)(h,{verse:24,children:"Shew me a penny. Whose image and inscription hath it? They answering, said to him: Caesar's."}),"\n",(0,n.jsx)(h,{verse:25,children:"And he said to them: Render therefore to Caesar the things, that are Caesar's: and to God the things that are God's."}),"\n",(0,n.jsx)(h,{verse:26,children:"And they could not reprehend his word before the people: and wondering at his answer, they held their peace."}),"\n",(0,n.jsx)(h,{verse:27,children:"And there came to him some of the Sadducees, who deny that there is any resurrection: and they asked him,"}),"\n",(0,n.jsx)(h,{verse:28,children:"Saying: Master, Moses wrote unto us: If any man's brother die, having a wife, and he leave no children, that his brother should take her to wife and raise up seed unto his brother."}),"\n",(0,n.jsx)(h,{verse:29,children:"There were therefore seven brethren: and the first took a wife and died without children."}),"\n",(0,n.jsx)(h,{verse:30,children:"And the next took her to wife: and he also died childless."}),"\n",(0,n.jsx)(h,{verse:31,children:"And the third took her. And in like manner, all the seven: and they left no children and died."}),"\n",(0,n.jsx)(h,{verse:32,children:"Last of all the woman died also."}),"\n",(0,n.jsx)(h,{verse:33,children:"In the resurrection therefore, whose wife of them shall she be? For all the seven had her to wife."}),"\n",(0,n.jsx)(h,{verse:34,children:"And Jesus said to them: The children of this world marry and are given in marriage:"}),"\n",(0,n.jsx)(h,{verse:35,children:"But they that shall be accounted worthy of that world and of the resurrection from the dead shall neither be married nor take wives."}),"\n",(0,n.jsx)(h,{verse:36,children:"Neither can they die any more for they are equal to the angels and are the children of God, being the children of the resurrection."}),"\n",(0,n.jsx)(h,{verse:37,children:"Now that the dead rise again, Moses also shewed at the bush, when he called the Lord: The God of Abraham and the God of Isaac and the God of Jacob."}),"\n",(0,n.jsx)(h,{verse:38,children:"For he is not the God of the dead, but of the living: for all live to him."}),"\n",(0,n.jsx)(h,{verse:39,children:"And some of the scribes answering, said to him: Master, thou hast said well."}),"\n",(0,n.jsx)(h,{verse:40,children:"And after that they durst not ask him any more questions."}),"\n",(0,n.jsx)(h,{verse:41,children:"But he said to them: How say they that Christ is the son of David?"}),"\n",(0,n.jsx)(h,{verse:42,children:"And David himself saith in the book of Psalms: The Lord said to my Lord, sit thou on my right hand,"}),"\n",(0,n.jsx)(h,{verse:43,children:"Till I make thy enemies thy footstool."}),"\n",(0,n.jsx)(h,{verse:44,children:"David then calleth him Lord. And how is he his son?"}),"\n",(0,n.jsx)(h,{verse:45,children:"And in the hearing of all the people, he said to his disciples:"}),"\n",(0,n.jsx)(h,{verse:46,children:"Beware of the scribes, who desire to walk in long robes and love salutations in the market place and the first chairs in the synagogues and the chief rooms at feasts:"}),"\n",(0,n.jsx)(h,{verse:47,children:"Who devour the houses of widows, feigning long prayer. These shall receive greater damnation."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>r,x:()=>o});var n=h(14041);const s={},i=n.createContext(s);function r(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);